// Test fixtures built from the sample: its agent.json, changed, written to a fresh temp directory.
// The shared fixtures stay as they are (`emitted` is generated by Julia).
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// compiled to dist/test/, so the source fixture is two levels up at <pkg>/test/fixtures
const here = dirname(fileURLToPath(import.meta.url));
export const sample = resolve(here, "../../test/fixtures/sample");

/** Write the sample agent.json, as `change` leaves it, to a new directory; returns the directory. */
export function writeVariant(change: (doc: any) => void): string {
  const doc = JSON.parse(readFileSync(resolve(sample, "agent.json"), "utf8"));
  change(doc);
  const dir = mkdtempSync(join(tmpdir(), "pinax-mcp-variant-"));
  writeFileSync(join(dir, "agent.json"), JSON.stringify(doc));
  return dir;
}

/**
 * The sample with one of every node a search reaches, each holding a token found nowhere else:
 * a code block (with and without a caption), a two-line prose block, a raw block, and a comment on
 * a table, a page and a section.
 */
export function everyNodeVariant(): string {
  return writeVariant((doc) => {
    const p1 = doc.pages.find((p: { id: string }) => p.id === "p1");
    const s1 = p1.sections[0];
    p1.texts[0].text = "headline\nzqtexttoken";
    p1.codes = [
      { id: "p1_code1", lang: "julia", source: "first_line()\nzqcodetoken()", output: "" },
      { id: "p1_code2", caption: "a captioned block", lang: "julia", source: "x = 1\ny = 2", output: "" },
    ];
    p1.raws = [{ id: "p1_raw1", html: "<div>\nzqrawtoken</div>" }];
    p1.tables[0].comments = [{ author: "me", text: "zqtablecomment" }];
    p1.comments = [{ author: "me", text: "zqpagecomment" }];
    s1.comments = [{ author: "me", text: "zqsectioncomment" }];
  });
}
